async function execute(browser: WebFlowBrowserAPI, params: FlowParams): Promise<WebFlowResult> {
    const input = await browser.selectElement({
        condition: 'The product search input in the main document, not a newsletter, account or address field' + (params.selectionCriteria ? '. Search request context: ' + JSON.stringify(params.productName + ' ' + params.selectionCriteria) : ''),
        capability: 'fill',
        frameScope: 'main-document'
    });
    await browser.executeUiAction(input.targetId, { type: 'fill', text: params.productName, submit: true });
    await browser.awaitPageLoad(params.navigationTimeoutMs);
    const result = await browser.evaluatePageCondition('The main document displays search results for the query ' + JSON.stringify(params.productName) + ', or an explicit no-results message for that query.', 'main-document');
    if (result.status !== 'matched') {
        throw new Error('Search result was not verified (' + result.status + '). The form may have been submitted; no retry.');
    }
    return { success: true, message: 'Verified main-document search results for ' + params.productName };
}
